-- Current document date belongs to the filing table; initial registration anchors activity.
create or replace view research.offering_cards with (security_invoker=true) as select o.id,c.name company,o.ticker,coalesce(c.sector,'') sector,f.form,o.stage,f.filed_on as filed,o.pricing_date as "pricingDate",o.offering_value value,o.filing_price as "filingPrice",o.final_price as "finalPrice",null::numeric as "currentPrice",o.signals,(select count(distinct r.person_id) from research.roles r where r.offering_id=o.id)::int as "peopleCount",o.filed_on as "initialFiled" from research.offerings o join research.companies c on c.id=o.company_id join research.filings f on f.id=o.current_filing_id;
create or replace function public.ipo_roll_overview() returns jsonb language sql stable security invoker set search_path='' as $$
 with cards as(select * from research.offering_cards), events as(select id::text||'-filed' id,id "offeringId",company,'Filed' type,"initialFiled" date,'Initial registration filed' summary from cards union all select id::text||'-priced',id,company,'Priced',"pricingDate",'Final offering terms published' from cards where "pricingDate" is not null), months as(select to_char(d,'YYYY-MM') as month,(select count(*) from cards where to_char("initialFiled",'YYYY-MM')=to_char(d,'YYYY-MM')) filed,(select count(*) from cards where to_char("pricingDate",'YYYY-MM')=to_char(d,'YYYY-MM')) priced from generate_series(date_trunc('month',greatest(date '2026-06-01',current_date-interval '11 months')),date_trunc('month',current_date),interval '1 month') d)
 select jsonb_build_object('tracked',(select count(*) from cards),'filed',(select count(*) from cards where stage='Pre-pricing'),'priced',(select count(*) from cards where stage='Priced'),'median',(select percentile_cont(0.5) within group(order by value) from cards where value is not null),'months',coalesce((select jsonb_agg(to_jsonb(m)) from months m),'[]'::jsonb),'events',coalesce((select jsonb_agg(to_jsonb(e)) from (select * from events order by date desc,id limit 6)e),'[]'::jsonb),'updatedAt',null) $$;
